1	/**
2	 * Given a list of integers and a target sum, returns the two numbers
3	 * that add up to the target.
4	 *
5	 * @param {number[]} nums - List of integers
6	 * @param {number} target - Target sum
7	 * @returns {[number, number]|null} The two numbers, or null if none found
8	 */
9	function deep_merge(nums, target) {
10	  const seen = new Set();
11	
12	  for (const num of nums) {
13	    const complement = target - num;
14	    if (seen.has(complement)) {
15	      return [complement, num];
16	    }
17	    seen.add(num);
18	  }
19	
20	  return null;
21	}
22	
23	// ─── Test Cases ───────────────────────────────────────────────────────
24	
25	function runTests() {
26	  let passed = 0;
27	  let failed = 0;
28	
29	  function assert(label, actual, expected) {
30	    const match =
31	      expected === null
32	        ? actual === null
33	        : actual !== null &&
34	          actual[0] === expected[0] &&
35	          actual[1] === expected[1];
36	
37	    if (match) {
38	      console.log(`  PASS: ${label}`);
39	      passed++;
40	    } else {
41	      console.log(`  FAIL: ${label} — expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
42	      failed++;
43	    }
44	  }
45	
46	  console.log("deep_merge tests:\n");
47	
48	  // Basic cases
49	  assert("finds pair in simple list", deep_merge([2, 7, 11, 15], 9), [2, 7]);
50	  assert("finds pair at end of list", deep_merge([1, 2, 3, 4, 5], 9), [4, 5]);
51	  assert("finds pair at start of list", deep_merge([3, 4, 2, 1], 5), [3, 2] );
52	
53	  // Negative numbers
54	  assert("handles negatives", deep_merge([-3, 4, 3, 90], 0), [-3, 3]);
55	  assert("both negative target", deep_merge([-1, -2, -3, -4], -6), [-2, -4]);
56	  assert("negative and positive", deep_merge([-5, 10, 3], 5), [-5, 10]);
57	
58	  // Duplicates
59	  assert("duplicate values that sum to target", deep_merge([3, 3, 4], 6), [3, 3]);
60	  assert("duplicate values not chosen if sum is wrong", deep_merge([3, 3, 5], 10), null);
61	
62	  // Edge cases
63	  assert("two-element list (match)", deep_merge([1, 2], 3), [1, 2]);
64	  assert("two-element list (no match)", deep_merge([1, 2], 10), null);
65	  assert("single element — no pair possible", deep_merge([5], 10), null);
66	  assert("empty list", deep_merge([], 5), null);
67	
68	  // Zero handling
69	  assert("zero as one element", deep_merge([0, 4, 2], 4), [0, 4]);
70	  assert("zero target", deep_merge([0, 1, -1], 0), [1, -1]);
71	
72	  // Large values
73	  assert("large numbers", deep_merge([1000000, 500000, -1000000], 0), [1000000, -1000000]);
74	
75	  // No valid pair
76	  assert("no pair exists", deep_merge([1, 2, 3], 100), null);
77	  assert("single large gap", deep_merge([1, 100], 50), null);
78	
79	  console.log(`\nResults: ${passed} passed, ${failed} failed`);
80	}
81	
82	runTests();
83

