61	  console.log('infixToPostfix tests:\n');
62	
63	  // Basic operations
64	  assertEqual(infixToPostfix('3 + 4'), '3 4 +', 'simple addition');
65	  assertEqual(infixToPostfix('5 - 2'), '5 2 -', 'simple subtraction');
66	  assertEqual(infixToPostfix('6 * 3'), '6 3 *', 'simple multiplication');
67	  assertEqual(infixToPostfix('8 / 4'), '8 4 /', 'simple division');
68	
