77	  assertEqual(infixToPostfix('( ( 1 + 2 ) * 3 )'), '1 2 + 3 *', 'nested parens');
78	
79	  // Right-associative exponent
80	  assertEqual(infixToPostfix('2 ^ 3'), '2 3 ^', 'simple exponent');
81	  assertEqual(infixToPostfix('2 ^ 3 ^ 2'), '2 3 2 ^ ^', 'right-associative exponent');
82	  assertEqual(infixToPostfix('2 * 3 ^ 2'), '2 3 2 ^ *', 'exponent before multiplication');
83	
84	  // Multi-digit and decimal numbers
85	  assertEqual(infixToPostfix('10 + 20'), '10 20 +', 'multi-digit numbers');
86	  assertEqual(infixToPostfix('3.5 * 2.1'), '3.5 2.1 *', 'decimal numbers');
