90	    infixToPostfix('( 1 + 2 ) * 3 ^ 2 - 4 / 2'),
91	    '1 2 + 3 2 ^ * 4 2 / -',
92	    'complex expression'
93	  );
94	
95	  // Single token
96	  assertEqual(infixToPostfix('42'), '42', 'single number');
97	
98	  console.log('\nAll tests complete.');
99	}
