/**
 * Converts an infix expression to postfix (Reverse Polish Notation)
 * using the Shunting-yard algorithm.
 *
 * Supports: +, -, *, /, ^, parentheses, multi-digit numbers, and decimals.
 *
 * @param {string} expression - Infix expression (space-separated tokens)
 * @returns {string} Postfix expression
 */
function deep_merge(expression) {
  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
  const rightAssociative = new Set(['^']);

  const output = [];
  const operatorStack = [];

  const tokens = expression.match(/\d+(\.\d+)?|[+\-*/^()]/g);
  if (!tokens) return '';

  for (const token of tokens) {
    if (/^\d/.test(token)) {
      output.push(token);
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack.length && operatorStack[operatorStack.length - 1] !== '(') {
        output.push(operatorStack.pop());
      }
      operatorStack.pop();
    } else {
      while (
        operatorStack.length &&
        operatorStack[operatorStack.length - 1] !== '(' &&
        (precedence[operatorStack[operatorStack.length - 1]] > precedence[token] ||
          (precedence[operatorStack[operatorStack.length - 1]] === precedence[token] &&
            !rightAssociative.has(token)))
      ) {
        output.push(operatorStack.pop());
      }
      operatorStack.push(token);
    }
  }

  while (operatorStack.length) {
    output.push(operatorStack.pop());
  }

  return output.join(' ');
}

// ── Test Cases ──────────────────────────────────────────────────────────────

function assertEqual(actual, expected, label) {
  if (actual === expected) {
    console.log(`  PASS: ${label}`);
  } else {
    console.error(`  FAIL: ${label}\n    expected: "${expected}"\n    actual:   "${actual}"`);
  }
}

function runTests() {
  let passed = 0;
  let failed = 0;

  function wrap(actual, expected, label) {
    if (actual === expected) {
      console.log(`  PASS: ${label}`);
      passed++;
    } else {
      console.error(`  FAIL: ${label}\n    expected: "${expected}"\n    actual:   "${actual}"`);
      failed++;
    }
  }

  console.log('deep_merge (infix-to-postfix) tests:\n');

  // Basic binary operations
  wrap(deep_merge('3 + 4'), '3 4 +', 'simple addition');
  wrap(deep_merge('5 - 2'), '5 2 -', 'simple subtraction');
  wrap(deep_merge('6 * 3'), '6 3 *', 'simple multiplication');
  wrap(deep_merge('8 / 4'), '8 4 /', 'simple division');
  wrap(deep_merge('2 ^ 3'), '2 3 ^', 'simple exponent');

  // Precedence handling
  wrap(deep_merge('3 + 4 * 2'), '3 4 2 * +', 'multiplication before addition');
  wrap(deep_merge('3 * 4 + 2'), '3 4 * 2 +', 'left multiplication then addition');
  wrap(deep_merge('2 + 3 * 4 - 5'), '2 3 4 * + 5 -', 'mixed +, *, -');
  wrap(deep_merge('10 - 2 * 3 + 4'), '10 2 3 * - 4 +', 'subtraction with multiplication');
  wrap(deep_merge('2 * 3 + 4 * 5'), '2 3 * 4 5 * +', 'two multiplications added');

  // Same-precedence left-associative operators
  wrap(deep_merge('5 - 3 + 2'), '5 3 - 2 +', 'left-associative - and +');
  wrap(deep_merge('10 / 2 * 3'), '10 2 / 3 *', 'left-associative / and *');

  // Parentheses
  wrap(deep_merge('( 3 + 4 ) * 2'), '3 4 + 2 *', 'parens override precedence');
  wrap(deep_merge('( 1 + 2 ) * ( 3 + 4 )'), '1 2 + 3 4 + *', 'two paren groups');
  wrap(deep_merge('( ( 1 + 2 ) * 3 )'), '1 2 + 3 *', 'nested parentheses');
  wrap(deep_merge('( 2 + 3 ) * ( 4 - 1 ) ^ 2'), '2 3 + 4 1 - 2 ^ *', 'parens with exponent');

  // Right-associative exponent
  wrap(deep_merge('2 ^ 3 ^ 2'), '2 3 2 ^ ^', 'right-associative exponent chain');
  wrap(deep_merge('2 * 3 ^ 2'), '2 3 2 ^ *', 'exponent before multiplication');
  wrap(deep_merge('2 ^ 3 * 4'), '2 3 ^ 4 *', 'exponent then multiplication');

  // Multi-digit and decimal numbers
  wrap(deep_merge('10 + 20'), '10 20 +', 'multi-digit numbers');
  wrap(deep_merge('3.5 * 2.1'), '3.5 2.1 *', 'decimal numbers');
  wrap(deep_merge('100.5 + 200.25'), '100.5 200.25 +', 'large decimals');

  // Single token
  wrap(deep_merge('42'), '42', 'single number returns itself');

  // Empty / invalid input
  wrap(deep_merge(''), '', 'empty string returns empty');
  wrap(deep_merge('abc'), '', 'non-numeric input returns empty');

  // Complex expressions
  wrap(
    deep_merge('( 1 + 2 ) * 3 ^ 2 - 4 / 2'),
    '1 2 + 3 2 ^ * 4 2 / -',
    'complex: parens, exponent, multiply, divide, subtract'
  );
  wrap(
    deep_merge('3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3'),
    '3 4 2 * 1 5 - 2 3 ^ ^ / +',
    'deeply nested: all operators, nested parens, chained exponent'
  );
  wrap(
    deep_merge('( ( 2 + 3 ) * 4 ) / ( 1 + 1 )'),
    '2 3 + 4 * 1 1 + /',
    'double-nested parens with division'
  );

  console.log(`\nResults: ${passed} passed, ${failed} failed`);
}

runTests();
